  locals { xs x i } {
    [ i xs prim seq-int.len prim < ]
    [
      i xs prim seq-int.at
      x prim =
      [ i ]
      [
        i 1 prim +
        find-helper
      ]
      if
    ]
    [
      -1
    ] if
